PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE admins (
  id          TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  username    TEXT NOT NULL UNIQUE,
  password    TEXT NOT NULL,
  nama_lengkap TEXT,
  created_at  TEXT DEFAULT (datetime('now'))
);
CREATE TABLE pendaftar (
  id                          TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  created_at                  TEXT DEFAULT (datetime('now')),
  no_pendaftaran              TEXT,
  ruang_tes                   TEXT,
  status_kelulusan            TEXT DEFAULT 'PENDING',  -- PENDING | DITERIMA | TIDAK DITERIMA
  status_verifikasi           INTEGER,                 -- NULL=pending, 1=diterima, 0=ditolak
  jalur                       TEXT NOT NULL,           -- REGULER | PRESTASI
  nisn                        TEXT NOT NULL,
  nik                         TEXT NOT NULL,
  nama_lengkap                TEXT NOT NULL,
  jenis_kelamin               TEXT,
  tempat_lahir                TEXT,
  tanggal_lahir               TEXT,
  ukuran_baju                 TEXT,
  agama                       TEXT DEFAULT 'Islam',
  jumlah_saudara              INTEGER,
  anak_ke                     INTEGER,
  status_anak                 TEXT,
  provinsi                    TEXT,
  kabupaten_kota              TEXT,
  kecamatan                   TEXT,
  desa_kelurahan              TEXT,
  rt                          TEXT,
  rw                          TEXT,
  alamat_lengkap              TEXT,
  kode_pos                    TEXT,
  no_kk                       TEXT,
  nama_ayah                   TEXT,
  nik_ayah                    TEXT,
  tempat_lahir_ayah           TEXT,
  tanggal_lahir_ayah          TEXT,
  status_ayah                 TEXT,
  pendidikan_ayah             TEXT,
  pekerjaan_ayah              TEXT,
  penghasilan_ayah            REAL,
  nama_ibu                    TEXT,
  nik_ibu                     TEXT,
  tempat_lahir_ibu            TEXT,
  tanggal_lahir_ibu           TEXT,
  status_ibu                  TEXT,
  pendidikan_ibu              TEXT,
  pekerjaan_ibu               TEXT,
  penghasilan_ibu             REAL,
  no_telepon_ortu             TEXT,
  nama_wali                   TEXT,
  nik_wali                    TEXT,
  tempat_lahir_wali           TEXT,
  tanggal_lahir_wali          TEXT,
  pendidikan_wali             TEXT,
  pekerjaan_wali              TEXT,
  penghasilan_wali            REAL,
  no_telepon_wali             TEXT,
  asal_sekolah                TEXT,
  npsn_sekolah                TEXT,
  status_sekolah              TEXT,
  alamat_sekolah              TEXT,
  pilihan_pesantren           TEXT,
  foto_url                    TEXT,
  scan_kk_url                 TEXT,
  scan_akta_url               TEXT,
  scan_kelakuan_baik_url      TEXT,
  scan_ktp_ortu_url           TEXT,
  scan_sertifikat_prestasi_url TEXT,
  scan_rapor_url              TEXT,
  tanggal_tes                 TEXT,
  sesi_tes                    TEXT
, berkas_ditolak TEXT DEFAULT NULL, nilai_rapor TEXT, daftar_ulang_pesantren_url TEXT, daftar_ulang_tertib_url TEXT, daftar_ulang_hardcopy_status TEXT DEFAULT NULL, daftar_ulang_hardcopy_at TEXT DEFAULT NULL);
CREATE TABLE prestasi (
  id              TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  pendaftar_id    TEXT,
  kategori        TEXT,
  nama_lomba      TEXT,
  penyelenggara   TEXT,
  tingkat         TEXT,
  tahun_perolehan TEXT,
  FOREIGN KEY (pendaftar_id) REFERENCES pendaftar(id)
);
CREATE TABLE pengaturan (
  key       TEXT PRIMARY KEY,
  value     TEXT,
  is_active INTEGER DEFAULT 1
);
CREATE TABLE cbt_rooms (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  room_name TEXT NOT NULL,
  capacity INTEGER DEFAULT 40,
  created_at TEXT DEFAULT (datetime('now'))
, event_id TEXT REFERENCES cbt_events(id));
CREATE TABLE cbt_exams (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  title TEXT NOT NULL,
  description TEXT,
  duration_minutes INTEGER NOT NULL DEFAULT 60,
  rules_text TEXT,
  completion_message TEXT DEFAULT 'Ujian telah selesai. Terima kasih.',
  is_score_visible INTEGER DEFAULT 0,
  randomize_questions INTEGER DEFAULT 0,
  randomize_options INTEGER DEFAULT 0,
  active_status TEXT DEFAULT 'draft' CHECK (active_status IN ('draft', 'active', 'finished')),
  passing_score REAL DEFAULT 0,
  created_by TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
, target_jalur TEXT DEFAULT NULL, cheat_limit INTEGER DEFAULT 3, cheat_action TEXT DEFAULT 'lock', enforce_fullscreen INTEGER DEFAULT 0, event_id TEXT REFERENCES cbt_events(id), subject_name TEXT, sequence_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE cbt_questions (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  exam_id TEXT NOT NULL REFERENCES cbt_exams(id) ON DELETE CASCADE,
  question_order INTEGER NOT NULL DEFAULT 0,
  question_text TEXT NOT NULL,
  question_type TEXT DEFAULT 'multiple_choice' CHECK (question_type IN ('multiple_choice', 'essay')),
  image_url TEXT,
  audio_url TEXT,
  points REAL DEFAULT 1,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE cbt_question_options (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  question_id TEXT NOT NULL REFERENCES cbt_questions(id) ON DELETE CASCADE,
  option_label TEXT NOT NULL,
  option_text TEXT NOT NULL,
  image_url TEXT,
  is_correct INTEGER DEFAULT 0,
  option_order INTEGER DEFAULT 0
);
CREATE TABLE cbt_student_answers (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  session_id TEXT NOT NULL REFERENCES cbt_exam_sessions(id) ON DELETE CASCADE,
  question_id TEXT NOT NULL REFERENCES cbt_questions(id) ON DELETE CASCADE,
  selected_option_id TEXT REFERENCES cbt_question_options(id),
  essay_answer TEXT,
  is_doubtful INTEGER DEFAULT 0,
  answered_at TEXT DEFAULT (datetime('now')),
  UNIQUE(session_id, question_id)
);
CREATE TABLE cbt_exam_results (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  session_id TEXT NOT NULL UNIQUE REFERENCES cbt_exam_sessions(id) ON DELETE CASCADE,
  exam_id TEXT NOT NULL REFERENCES cbt_exams(id),
  user_id TEXT NOT NULL,
  user_type TEXT NOT NULL DEFAULT 'pendaftar',
  total_questions INTEGER DEFAULT 0,
  total_correct INTEGER DEFAULT 0,
  total_wrong INTEGER DEFAULT 0,
  total_unanswered INTEGER DEFAULT 0,
  score REAL DEFAULT 0,
  computed_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS "cbt_users" (id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT, nama_lengkap TEXT, role TEXT NOT NULL CHECK(role IN ('admin','proctor','student')), room_id TEXT, nisn TEXT, is_active INTEGER DEFAULT 1, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), FOREIGN KEY(room_id) REFERENCES cbt_rooms(id));
CREATE TABLE cbt_settings (   key TEXT PRIMARY KEY,   value TEXT NOT NULL,   updated_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE cbt_exam_assignments (   id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),   exam_id TEXT NOT NULL,   user_id TEXT NOT NULL,   user_type TEXT NOT NULL DEFAULT 'pendaftar',   created_at TEXT DEFAULT (datetime('now')),   UNIQUE(exam_id, user_id, user_type) );
CREATE TABLE cbt_cheat_logs (
  id             TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  session_id     TEXT NOT NULL REFERENCES cbt_exam_sessions(id) ON DELETE CASCADE,
  violation_type TEXT NOT NULL,   -- 'tab_switch' | 'fullscreen_exit'
  happened_at    TEXT NOT NULL
);
CREATE TABLE cbt_ai_generations (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  exam_id TEXT NOT NULL REFERENCES cbt_exams(id) ON DELETE CASCADE,
  created_by TEXT,
  generation_mode TEXT NOT NULL DEFAULT 'review' CHECK (generation_mode IN ('review', 'direct_save')),
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'imported')),
  model_name TEXT,
  request_payload TEXT,
  generated_payload TEXT,
  generated_count INTEGER DEFAULT 0,
  imported_count INTEGER DEFAULT 0,
  created_at TEXT DEFAULT (datetime('now')),
  imported_at TEXT,
  updated_at TEXT DEFAULT (datetime('now'))
, prompt_tokens INTEGER DEFAULT 0, completion_tokens INTEGER DEFAULT 0, estimated_neurons REAL DEFAULT 0);
CREATE TABLE IF NOT EXISTS "cbt_exam_tokens" ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), exam_id TEXT NOT NULL REFERENCES cbt_exams(id) ON DELETE CASCADE, room_id TEXT NOT NULL REFERENCES cbt_rooms(id) ON DELETE CASCADE, tanggal_tes TEXT NOT NULL DEFAULT '', sesi_tes TEXT NOT NULL DEFAULT '', token_code TEXT NOT NULL, is_active INTEGER DEFAULT 1, expires_at TEXT, created_at TEXT DEFAULT (datetime('now')), UNIQUE(exam_id, room_id, tanggal_tes, sesi_tes) );
CREATE TABLE cbt_events (
  id TEXT PRIMARY KEY,
  code TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  activity_type TEXT NOT NULL DEFAULT 'other',
  participant_source TEXT NOT NULL CHECK (participant_source IN ('pmb', 'mansatas', 'cbt_user')),
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('draft', 'active', 'archived')),
  created_by TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE cbt_exam_roster (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  exam_id TEXT NOT NULL REFERENCES cbt_exams(id) ON DELETE CASCADE,
  event_id TEXT NOT NULL REFERENCES cbt_events(id),
  source_key TEXT NOT NULL CHECK (source_key IN ('pmb', 'mansatas', 'cbt_user')),
  source_id TEXT NOT NULL,
  username TEXT NOT NULL,
  nisn TEXT,
  full_name TEXT NOT NULL,
  class_name TEXT,
  grade TEXT,
  gender TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  metadata_json TEXT,
  room_id TEXT REFERENCES cbt_rooms(id),
  tanggal_tes TEXT NOT NULL DEFAULT '',
  sesi_tes TEXT NOT NULL DEFAULT '',
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  UNIQUE(exam_id, source_key, source_id)
);
CREATE TABLE IF NOT EXISTS "cbt_exam_sessions" (
  id TEXT PRIMARY KEY,
  exam_id TEXT NOT NULL REFERENCES cbt_exams(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL,
  user_type TEXT NOT NULL DEFAULT 'pendaftar' CHECK (user_type IN ('pendaftar', 'mansatas', 'cbt_user')),
  room_id TEXT NOT NULL,
  device_id TEXT,
  status TEXT DEFAULT 'active' CHECK (status IN ('active', 'paused', 'submitted', 'force_submitted')),
  cheat_warnings INTEGER DEFAULT 0,
  question_map TEXT,
  option_map TEXT,
  started_at TEXT DEFAULT (datetime('now')),
  finished_at TEXT,
  last_heartbeat TEXT DEFAULT (datetime('now')),
  is_time_locked INTEGER DEFAULT 0,
  locked_at TEXT,
  ip_address TEXT,
  user_agent TEXT,
  UNIQUE(exam_id, user_id, user_type)
);
CREATE INDEX idx_cbt_exams_status ON cbt_exams(active_status);
CREATE INDEX idx_cbt_questions_exam ON cbt_questions(exam_id, question_order);
CREATE INDEX idx_cbt_options_question ON cbt_question_options(question_id);
CREATE INDEX idx_cbt_answers_session ON cbt_student_answers(session_id);
CREATE INDEX idx_cbt_results_exam ON cbt_exam_results(exam_id);
CREATE INDEX idx_cbt_assignments_exam ON cbt_exam_assignments(exam_id);
CREATE INDEX idx_cbt_assignments_user ON cbt_exam_assignments(user_id, user_type);
CREATE INDEX idx_cheat_logs_session ON cbt_cheat_logs(session_id);
CREATE INDEX idx_cbt_ai_generations_exam ON cbt_ai_generations(exam_id, created_at DESC);
CREATE INDEX idx_cbt_tokens_lookup ON cbt_exam_tokens(exam_id, room_id, tanggal_tes, sesi_tes, token_code);
CREATE INDEX idx_cbt_exams_event ON cbt_exams(event_id);
CREATE INDEX idx_cbt_roster_exam ON cbt_exam_roster(exam_id, room_id);
CREATE INDEX idx_cbt_roster_source ON cbt_exam_roster(source_key, source_id);
CREATE INDEX idx_cbt_sessions_exam ON cbt_exam_sessions(exam_id, status);
CREATE INDEX idx_cbt_sessions_room ON cbt_exam_sessions(room_id, status);
